1	package viewer
2	
3	import (
4		"strings"
5	
6		"github.com/anthnel/devdesk/internal/ui/components"
7		"github.com/anthnel/devdesk/internal/ui/theme"
8		"github.com/anthnel/devdesk/internal/viewer"
9	)
10	
11	// rebuildText renders the text pane and hands it to the viewport.
12	//
13	// It is called when the document loads, when `c`, `w` or `v` changes, when the
14	// search query changes and when the width changes — and at no other time.
15	// View() must stay read-only (Rule 110), and re-rendering five megabytes per
16	// frame would not be viable even if it did not.
17	func (m *Model) rebuildText() {
18		width := m.textViewport.Width
19		query := strings.ToLower(strings.TrimSpace(m.bar.SearchQuery()))
20		isLog := m.doc.Kind == viewer.KindLog
21	
22		var out []string
23		m.matchedLines = 0
24	
25		for _, line := range m.lines {
26			if isLog && !line.Level.Passes(m.minLevel) {
27				continue
28			}
29			if query != "" && !strings.Contains(strings.ToLower(line.Plain), query) {
30				continue
31			}
32			m.matchedLines++
33	
34			segments := [][]viewer.Token{line.Tokens}
35			if m.wrap && width > 0 {
36				segments = wrapTokens(line.Tokens, width)
37			}
38			for _, segment := range segments {
39				// Padded to the full width: lipgloss inherits no background
40				// (Rule 115), so a line shorter than the pane would show the
41				// terminal's own from its last character to the right margin.
42				out = append(out, theme.PadWithBg(renderSegment(segment, line.Level, isLog), width))
43			}
44		}
45	
46		if len(out) == 0 {
47			out = append(out, theme.PadWithBg(theme.DimStyle.Render(m.emptyTextMessage()), width))
48		}
49	
50		m.textViewport.SetContent(strings.Join(out, "\n"))
51	}
52	
53	// emptyTextMessage says why the pane is empty, which is never obvious: an empty
54	// document, a filter that matched nothing and a search that matched nothing all
55	// look identical, and only one of them is the user's own doing.
56	func (m *Model) emptyTextMessage() string {
57		switch {
58		case m.bar.SearchQuery() != "":
59			return "No line matches " + m.bar.SearchQuery()
60		case m.minLevel != viewer.LevelUnknown:
61			return "No line at " + minLevelLabel(m.minLevel) + " or above"
62		default:
63			return "Empty document"
64		}
65	}
66	
67	// minLevelLabel is how a verbosity filter reads, in the footer token and in the
68	// header alike — one spelling, so the two cannot drift.
69	func minLevelLabel(level viewer.Level) string {
70		if level == viewer.LevelUnknown {
71			return "all"
72		}
73		return "≥ " + level.String()
74	}
75	
76	// cycleVerbosity advances the minimum level: all, then each level in turn, then
77	// back to all.
78	//
79	// One key rather than four toggles, because a minimum is what "verbosity" means
80	// and log levels are monotone — nobody wants warn but not error. The bar shows
81	// it as a single token, and disappears entirely at `all` (Rule 136: no filter,
82	// no bar).
83	func (m *Model) cycleVerbosity() {
84		next := viewer.LevelUnknown
85		switch m.minLevel {
86		case viewer.LevelUnknown:
87			next = viewer.Levels[0]
88		default:
89			for i, level := range viewer.Levels {
90				if level == m.minLevel && i+1 < len(viewer.Levels) {
91					next = viewer.Levels[i+1]
92				}
93			}
94		}
95		m.minLevel = next
96		m.syncVerbosityToken()
97		m.rebuildText()
98	}
99	
100	// syncVerbosityToken keeps the filter bar's token showing the level in force.
101	//
102	// The label carries the value, so SetTokens is given the active flag explicitly:
103	// it preserves an active state by matching labels, and "≥ warn" is not the label
104	// "≥ info" was.
105	func (m *Model) syncVerbosityToken() {
106		if m.doc.Kind != viewer.KindLog || m.minLevel == viewer.LevelUnknown {
107			m.bar.SetTokens(nil)
108			return
109		}
110		m.bar.SetTokens([]components.FilterToken{{Label: minLevelLabel(m.minLevel), Active: true}})
111	}
112

1	package viewer
2	
3	import (
4		"strings"
5	
6		"github.com/anthnel/devdesk/internal/viewer"
7	)
8	
9	// docLine is one source line, kept as the token spans it is made of.
10	//
11	// The spans are the point. Wrapping counts runes, and an ANSI escape's bytes
12	// count as width — the same hazard Rule 122 describes for table cells — so a
13	// line that has already been coloured cannot be wrapped without the cut landing
14	// inside an escape sequence. Keeping the line as tokens means it is wrapped
15	// while it is still plain and coloured afterwards, which is the only order that
16	// works.
17	type docLine struct {
18		Tokens []viewer.Token
19		Plain  string
20		Level  viewer.Level
21	}
22	
23	// buildLines splits a document into styled-per-line spans.
24	//
25	// It is called when the document loads and when `c` toggles, and not otherwise:
26	// tokenising five megabytes per frame is not viable, and the filter and the
27	// wrap both work on the result rather than redoing it.
28	func buildLines(doc viewer.Document, highlight bool) []docLine {
29		tokens := []viewer.Token{{Class: viewer.ClassText, Text: doc.Text}}
30		if highlight {
31			tokens = viewer.Tokenize(doc.Kind, doc.Text)
32		}
33	
34		lines := splitTokenLines(tokens)
35	
36		// A log's level rides on the line, not on a token. The two lists are the
37		// same split of the same text — ParseLog and splitTokenLines both cut on
38		// "\n" — so they line up index for index.
39		for i := range lines {
40			if i < len(doc.Lines) {
41				lines[i].Level = doc.Lines[i].Level
42			}
43		}
44		return lines
45	}
46	
47	// splitTokenLines cuts a document-wide token stream into one slice of tokens per
48	// line, splitting any token that spans a newline.
49	func splitTokenLines(tokens []viewer.Token) []docLine {
50		var lines []docLine
51		var current []viewer.Token
52		var plain strings.Builder
53	
54		flush := func() {
55			lines = append(lines, docLine{Tokens: current, Plain: plain.String()})
56			current = nil
57			plain.Reset()
58		}
59	
60		for _, token := range tokens {
61			parts := strings.Split(token.Text, "\n")
62			for i, part := range parts {
63				if i > 0 {
64					flush()
65				}
66				if part == "" {
67					continue
68				}
69				current = append(current, viewer.Token{Class: token.Class, Text: part})
70				plain.WriteString(part)
71			}
72		}
73		flush()
74	
75		// A document ending in a newline produces a trailing empty line, which is
76		// true of the text but renders as a blank row nobody asked for.
77		if n := len(lines); n > 1 && lines[n-1].Plain == "" {
78			lines = lines[:n-1]
79		}
80		return lines
81	}
82	
83	// wrapTokens splits a line into segments no wider than width runes, cutting
84	// tokens where a segment ends.
85	//
86	// It breaks at the width rather than at a word boundary, for the same reason
87	// viewer.WrapLines does: the content here is a log line, a stack trace or a
88	// minified document, where the columns carry meaning.
89	func wrapTokens(tokens []viewer.Token, width int) [][]viewer.Token {
90		if width <= 0 {
91			return [][]viewer.Token{tokens}
92		}
93	
94		var segments [][]viewer.Token
95		var current []viewer.Token
96		room := width
97	
98		for _, token := range tokens {
99			runes := []rune(token.Text)
100			for len(runes) > 0 {
101				if room == 0 {
102					segments = append(segments, current)
103					current, room = nil, width
104				}
105				take := min(room, len(runes))
106				current = append(current, viewer.Token{Class: token.Class, Text: string(runes[:take])})
107				runes = runes[take:]
108				room -= take
109			}
110		}
111		return append(segments, current)
112	}
113	
114	// render paints a segment. A log line takes one style for the whole of it, so
115	// that an ERROR is picked out at a glance; anything else is coloured token by
116	// token.
117	func renderSegment(tokens []viewer.Token, level viewer.Level, isLog bool) string {
118		if isLog {
119			var plain strings.Builder
120			for _, token := range tokens {
121				plain.WriteString(token.Text)
122			}
123			return levelStyle(level).Render(plain.String())
124		}
125	
126		var out strings.Builder
127		for _, token := range tokens {
128			out.WriteString(syntaxStyle(token.Class).Render(token.Text))
129		}
130		return out.String()
131	}
