1	package viewer
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/charmbracelet/lipgloss"
8	
9		"github.com/anthnel/devdesk/internal/ui/help"
10		"github.com/anthnel/devdesk/internal/ui/shortcut"
11		"github.com/anthnel/devdesk/internal/ui/theme"
12	)
13	
14	// View renders whichever half is on screen.
15	func (m Model) View() string {
16		contentStyle := lipgloss.NewStyle().Background(theme.ColorBackground).PaddingLeft(1)
17	
18		switch {
19		case m.loading:
20			return contentStyle.Render(theme.DimStyle.Render("\nLoading..."))
21		case !m.hasDocument():
22			return contentStyle.Render(theme.HelpStyle.Render("\nNothing open\n\nOpen a file from workspaces, or inspect a container."))
23		case m.display == displayTree:
24			return m.tree.View()
25		default:
26			return m.textViewport.View()
27		}
28	}
29	
30	// GetFooterHeight is Rule 124's budget: an empty line and an info line, plus the
31	// filter bar when it is showing.
32	func (m Model) GetFooterHeight() int {
33		return 2 + m.bar.ExtraHeight()
34	}
35	
36	// RenderFooter draws the filter bar and the one line of state.
37	func (m Model) RenderFooter(width int) string {
38		var parts []string
39		if m.bar.IsVisible() {
40			parts = append(parts, m.bar.View())
41		}
42		parts = append(parts, theme.EmptyLineBg(width), m.renderInfoLine(width))
43		return strings.Join(parts, "\n")
44	}
45	
46	func (m Model) renderInfoLine(width int) string {
47		if m.footerError != "" {
48			return theme.PadWithBg(theme.StatusErrorStyle.Render(m.footerError), width)
49		}
50		if m.footerInfo == "" {
51			return theme.EmptyLineBg(width)
52		}
53		return lipgloss.NewStyle().
54			Foreground(theme.ColorHighlight).
55			Background(theme.ColorBackground).
56			Width(width).
57			Align(lipgloss.Center).
58			Render(m.footerInfo)
59	}
60	
61	// ── HeaderView ───────────────────────────────────────────────────────────────
62	//
63	// All four methods. The router probes for the interface as a whole and falls
64	// back in silence, so a view supplying two of them renders an empty title with
65	// nothing to say why — which is what happened to the configuration view.
66	
67	func (m Model) GetTitle() string {
68		if name := m.Name(); name != "" {
69			return theme.IconCodeFile + " Viewer · " + name
70		}
71		return theme.IconCodeFile + " Viewer"
72	}
73	
74	func (m Model) GetIcon() string { return "" }
75	
76	func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
77		info := []shortcut.HeaderInfo{
78			{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
79			{Key: "Format", Value: m.formatLabel(), Style: theme.HeaderValueStyle},
80		}
81		if !m.hasDocument() {
82			return info
83		}
84		if m.structured() && m.display == displayTree {
85			return append(info, shortcut.HeaderInfo{
86				Key: "Nodes", Value: fmt.Sprintf("%d", m.doc.NodeCount()), Style: theme.HeaderValueStyle,
87			})
88		}
89		return append(info, shortcut.HeaderInfo{
90			Key: "Lines", Value: m.lineCount(), Style: theme.HeaderValueStyle,
91		})
92	}
93	
94	// lineCount says how many lines are showing, and out of how many when a filter
95	// is narrowing them. A bare count under an active filter would read as the size
96	// of the document, which is the one thing it is not.
97	func (m Model) lineCount() string {
98		total := len(m.lines)
99		if m.matchedLines == total {
100			return fmt.Sprintf("%d", total)
101		}
102		return fmt.Sprintf("%d/%d", m.matchedLines, total)
103	}
104	
105	// GetShortcuts is state-aware (Rule 130): every key that depends on the kind of
106	// document or on what its source can do is offered only when it would work.
107	func (m Model) GetShortcuts() shortcut.Shortcuts {
108		if !m.hasDocument() {
109			return []shortcut.Shortcut{{Key: "esc", Description: "Go back"}}
110		}
111	
112		var shortcuts []shortcut.Shortcut
113	
114		if m.structured() {
115			if m.display == displayTree {
116				shortcuts = append(shortcuts,
117					shortcut.Shortcut{Key: "←→", Description: "Collapse/Expand"},
118					shortcut.Shortcut{Key: "f", Description: "Show as text"},
119				)
120			} else {
121				shortcuts = append(shortcuts, shortcut.Shortcut{Key: "f", Description: "Show as tree"})
122			}
123		}
124	
125		if m.display == displayText {
126			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "w", Description: "Toggle wrap"})
127			if m.isLog() {
128				shortcuts = append(shortcuts, shortcut.Shortcut{Key: "v", Description: "Verbosity"})
129			}
130			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "/", Description: "Search"})
131		}
132	
133		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "c", Description: "Toggle coloring"})
134	
135		if _, ok := m.timestamps(); ok {
136			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "t", Description: "Toggle timestamps"})
137		}
138		if m.source != nil {
139			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "ctrl+r", Description: "Reload"})
140		}
141		if _, ok := m.followable(); ok {
142			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "F", Description: "Follow live output"})
143		}
144		if _, ok := m.pageable(); ok {
145			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "V", Description: "Open in system pager"})
146		}
147	
148		return append(shortcuts,
149			shortcut.Shortcut{Key: "esc", Description: "Go back"},
150			shortcut.Shortcut{Key: "?", Description: "Help"},
151		)
152	}
153	
154	// GetHelpContent implements help.Provider (Rule 114).
155	func (m Model) GetHelpContent() help.Content {
156		return help.Content{
157			Title: "Viewer",
158			Description: "A read-only view of one document. JSON and XML open on a navigable tree; " +
159				"logs open as text with a verbosity filter; everything else opens as text. " +
160				"The viewer is opened from another view — a file in workspaces, an inspect or a log in containers — and Esc returns there.",
161			KeyBindings: []help.KeyBinding{
162				{Key: "↑/k", Description: "Move up"},
163				{Key: "↓/j", Description: "Move down"},
164				{Key: "→/l", Description: "Expand the selected node (tree)"},
165				{Key: "←/h", Description: "Collapse the selected node (tree)"},
166				{Key: "f", Description: "Switch between the tree and the document's own text"},
167				{Key: "c", Description: "Turn syntax coloring on or off"},
168				{Key: "w", Description: "Soft-wrap long lines (text)"},
169				{Key: "v", Description: "Cycle the minimum log level shown (logs)"},
170				{Key: "/", Description: "Search the text"},
171				{Key: "t", Description: "Show or hide timestamps (container logs)"},
172				{Key: "ctrl+r", Description: "Reload from the source"},
173				{Key: "F", Description: "Follow live output (container logs)"},
174				{Key: "V", Description: "Open in the system pager (container logs)"},
175				{Key: "esc", Description: "Return to the view the document was opened from"},
176				{Key: "?", Description: "Show this help"},
177			},
178			Sections: []help.Section{
179				{
180					Title: "Tree and text",
181					Body: "A JSON or XML document opens on its tree: → expands a node, ← collapses it, and a closed " +
182						"container shows how many children it holds. Press f for the document's own text, exactly as it " +
183						"is on disk — press f again to come back. A document with no structure, including a log, has no " +
184						"tree and f does nothing.",
185				},
186				{
187					Title: "Coloring",
188					Body: "c turns syntax coloring on and off, in the tree and in the text alike. With it off the " +
189						"document reads as plain text. Colors follow the current theme; no document has colors of its own.",
190				},
191				{
192					Title: "Log verbosity",
193					Body: "v cycles the minimum level shown: all, trace, debug, info, warn, error. A line with no level " +
194						"of its own inherits the level of the line above it, so a stack trace stays with the error that " +
195						"raised it — filtering to 'warn and above' never breaks one apart. A line before any level at all " +
196						"is always shown.",
197				},
198				{
199					Title: "Reload and follow",
200					Body: "ctrl+r re-reads the document from where it came from — the file on disk, or docker. For " +
201						"container logs, ctrl+f follows live output and e opens the system pager; both suspend the TUI " +
202						"until you leave them, and the document is re-read on the way back.",
203				},
204				{
205					Title: "What will not open",
206					Body: "A file over 5 MB is refused, and so is a binary one: the footer says which. A malformed JSON " +
207						"or XML is not refused — it opens as text, with a note saying it would not parse, because it is " +
208						"exactly the file you need to look at.",
209				},
210			},
211		}
212	}
