8	// The invariant every caller depends on. The rendered lines are matched against
9	// the document's real ones, so a lexer that dropped or added a byte would
10	// desynchronise the two — and the failure would show up as a viewport scrolled
11	// to the wrong place, a long way from its cause.
12	func TestHighlightingReproducesTheInputExactly(t *testing.T) {
13		cases := []struct {
14			kind Kind
15			text string
16		}{
17			{KindJSON, "{\n  \"name\": \"nginx\",\n  \"n\": 42,\n  \"ok\": true,\n  \"z\": null\n}"},
18			{KindXML, "<?xml version=\"1.0\"?>\n<!-- c -->\n<root a=\"1\">text</root>\n"},
19			{KindPlain, "just\nsome\ttext\n"},
20			{KindLog, "2026-01-01 [ERROR] boom\n"},
21			{KindJSON, ""},
22			{KindJSON, "{not really json"},
23		}
24	
25		for _, tc := range cases {
26			var rebuilt strings.Builder
27			for _, token := range Tokenize(tc.kind, tc.text) {
28				rebuilt.WriteString(token.Text)
29			}
30			if rebuilt.String() != tc.text {
31				t.Errorf("%s: tokens rebuild %q, want %q", tc.kind, rebuilt.String(), tc.text)
32			}
33		}
34	}
35	
36	func TestJSONTokensAreClassified(t *testing.T) {
37		tokens := Tokenize(KindJSON, `{"name": "nginx", "n": 42, "ok": true}`)
38	
39		seen := map[TokenClass]string{}
40		for _, token := range tokens {
41			if _, ok := seen[token.Class]; !ok {
42				seen[token.Class] = token.Text
43			}
44		}
45	
46		for class, want := range map[TokenClass]string{
47			ClassKey:     `"name"`,
48			ClassString:  `"nginx"`,
49			ClassNumber:  `42`,
50			ClassLiteral: `true`,
51			ClassPunct:   `{`,
52		} {
53			if seen[class] != want {
54				t.Errorf("class %d first matched %q, want %q", class, seen[class], want)
55			}
56		}
57	}
58	
59	func TestXMLTagsAndAttributesAreClassifiedApart(t *testing.T) {
60		tokens := Tokenize(KindXML, `<!-- c --><root a="1">text</root>`)
61	
62		classes := map[TokenClass]bool{}
63		for _, token := range tokens {
64			classes[token.Class] = true
65		}
66		for _, want := range []TokenClass{ClassComment, ClassTag, ClassAttr, ClassString} {
67			if !classes[want] {
68				t.Errorf("class %d never appeared in an XML document that has one", want)
